CREATE OR REPLACE FUNCTION private.protect_super_admin()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op='DELETE' and old.management_role='super_admin' then
    raise exception 'protected super admin cannot be deleted' using errcode='42501';
  end if;
  if tg_op='UPDATE' and old.management_role='super_admin' and (
    new.user_id is distinct from old.user_id or new.email is distinct from old.email or
    new.management_role is distinct from old.management_role or new.role is distinct from old.role or
    new.is_active is distinct from old.is_active or new.disabled_at is distinct from old.disabled_at
  ) then raise exception 'protected super admin cannot be modified' using errcode='42501'; end if;
  if tg_op='DELETE' then return old; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.bootstrap_firebase_app_user(requested_firebase_uid text, requested_email text)
 RETURNS TABLE(user_id uuid, role app_role, is_active boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  normalized_requested_email text := lower(btrim(requested_email));
  matched public.app_users%rowtype;
begin
  if auth.role() <> 'service_role' then
    raise exception 'access denied' using errcode='42501';
  end if;
  if requested_firebase_uid is null
    or requested_firebase_uid <> btrim(requested_firebase_uid)
    or length(requested_firebase_uid) not between 1 and 128
    or requested_firebase_uid ~ '[[:space:]]'
    or normalized_requested_email !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' then
    raise exception 'access denied' using errcode='42501';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(normalized_requested_email,0));
  perform pg_advisory_xact_lock(hashtextextended(requested_firebase_uid,1));

  if exists (
    select 1 from public.app_users u
    where u.firebase_uid=requested_firebase_uid
      and u.email<>normalized_requested_email
  ) then
    raise exception 'identity conflict' using errcode='23505';
  end if;

  select * into matched from public.app_users u
  where u.email=normalized_requested_email
  for update;

  if not found or not matched.is_active then
    raise exception 'access denied' using errcode='42501';
  end if;
  if matched.firebase_uid is not null
    and matched.firebase_uid<>requested_firebase_uid then
    raise exception 'identity conflict' using errcode='23505';
  end if;

  update public.app_users u
  set firebase_uid=requested_firebase_uid,
      firebase_linked_at=coalesce(u.firebase_linked_at,now()),
      updated_at=now()
  where u.user_id=matched.user_id;

  return query select matched.user_id,matched.role,matched.is_active;
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_visual_index_job(p_job_id uuid, p_owner text, p_embedding jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare j public.asset_visual_index_jobs; v public.vector(512);
begin
  select * into j from public.asset_visual_index_jobs where id=p_job_id and status='PROCESSING' and claim_owner=p_owner for update;
  if not found then raise exception 'visual claim lost'; end if;
  if jsonb_array_length(p_embedding->'embedding')<>512 then raise exception 'visual embedding must contain 512 values'; end if;
  v := (p_embedding->'embedding')::text::public.vector(512);
  insert into public.asset_visual_embeddings(asset_id,model_provider,model_name,model_version,embedding_dimensions,embedding,source_fingerprint,source_method,frame_count,indexed_at)
  values(j.asset_id,j.model_provider,j.model_name,j.model_version,512,v,j.source_fingerprint,p_embedding->>'source_method',(p_embedding->>'frame_count')::integer,now())
  on conflict(asset_id,model_provider,model_name,model_version,source_fingerprint) do update set embedding=excluded.embedding,
    embedding_dimensions=512,source_method=excluded.source_method,frame_count=excluded.frame_count,updated_at=now(),indexed_at=now();
  update public.asset_visual_index_jobs set status='INDEXED',claim_owner=null,claimed_at=null,claim_expires_at=null,
    failure_code=null,failure_detail=null,completed_at=now(),updated_at=now() where id=p_job_id;
  return true;
end $function$

CREATE OR REPLACE FUNCTION public.enforce_search_assertion_evidence()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if new.search_critical and new.semantic_state='OBSERVED' and not exists(select 1 from public.semantic_assertion_evidence e where e.assertion_id=new.id) then
   raise exception 'search-critical OBSERVED assertion requires evidence';
 end if;
 if new.search_critical and new.semantic_state='FALSE' and not exists(select 1 from public.semantic_assertion_evidence e where e.assertion_id=new.id and e.polarity='NEGATIVE' and e.completeness='COMPLETE') then
   raise exception 'search-critical FALSE assertion requires complete negative evidence';
 end if; return new;
end $function$

CREATE OR REPLACE FUNCTION public.link_current_app_user()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  current_user_id uuid := (select auth.uid());
  auth_email text;
  approved public.approved_app_users%rowtype;
begin
  if current_user_id is null then raise exception 'authentication required' using errcode = '28000'; end if;
  select lower(btrim(u.email)) into auth_email from auth.users u where u.id = current_user_id and u.email_confirmed_at is not null;
  if auth_email is null then raise exception 'access denied' using errcode = '42501'; end if;
  select * into approved from public.approved_app_users a where a.normalized_email = auth_email and a.is_active;
  if not found then raise exception 'access denied' using errcode = '42501'; end if;
  insert into public.app_users(user_id,email,role,is_active,can_view_clinical,can_download,created_by)
  values(current_user_id,auth_email,approved.role,true,approved.can_view_clinical,approved.can_download,approved.created_by)
  on conflict(user_id) do update set
    email=excluded.email,role=excluded.role,is_active=true,
    can_view_clinical=excluded.can_view_clinical,can_download=excluded.can_download,
    disabled_at=null,updated_at=now();
end;
$function$

CREATE OR REPLACE FUNCTION public.prevent_signed_gold_child_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_set_id uuid; v_status text; v_old jsonb:=to_jsonb(old);
begin
 if tg_table_name='gold_standard_assets' then
   v_set_id:=(v_old->>'gold_set_id')::uuid;
 else
   select ga.gold_set_id into v_set_id from public.gold_standard_assets ga where ga.id=(v_old->>'gold_asset_id')::uuid;
 end if;
 select status into v_status from public.gold_standard_sets where id=v_set_id;
 if v_status='SIGNED_OFF' then raise exception 'signed-off gold children are immutable; create a new gold revision'; end if;
 return old;
end $function$

CREATE OR REPLACE FUNCTION public.release_synchronization_lock(requested_lock_name text, requested_run_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare affected bigint;
begin
  delete from public.synchronization_locks
  where lock_name=btrim(requested_lock_name) and owner_run_id=requested_run_id;
  get diagnostics affected = row_count;
  return affected = 1;
end $function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_step10_migration_event_legacy_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  legacy_status_constraint text;
  preferred_status text;
  fallback_status text;
begin
  if new.asset_destination_id is null
    or new.event_type not in (
      'LIFECYCLE_INITIALIZED',
      'UPLOAD_QUEUED',
      'UPLOAD_CLAIMED',
      'CLAIM_RENEWED',
      'CLAIM_RELEASED',
      'CLAIM_RECOVERED',
      'UPLOAD_STARTED',
      'UPLOAD_CREATED',
      'UPLOAD_RECOVERED',
      'UPLOAD_VERIFIED',
      'UPLOAD_FAILED',
      'UPLOAD_RETRY_SCHEDULED',
      'SOURCE_CHANGED',
      'SOURCE_NOT_FOUND',
      'SOURCE_ACCESS_DENIED',
      'DESTINATION_ACCESS_DENIED',
      'DESTINATION_CONFLICT',
      'MANUAL_REVIEW_REQUIRED'
    )
  then
    return new;
  end if;

  if new.status is not null then
    return new;
  end if;

  select string_agg(
    pg_catalog.pg_get_constraintdef(constraint_row.oid),
    ' '
  )
  into legacy_status_constraint
  from pg_catalog.pg_constraint as constraint_row
  join pg_catalog.pg_attribute as status_attribute
    on status_attribute.attrelid = constraint_row.conrelid
   and status_attribute.attname = 'status'
   and status_attribute.attnum = any(constraint_row.conkey)
  where constraint_row.conrelid = 'public.migration_events'::regclass
    and constraint_row.contype = 'c';

  case new.event_status
    when 'SUCCESS' then
      preferred_status := 'SUCCESS';
      fallback_status := 'COMPLETED';
    when 'ERROR' then
      preferred_status := 'ERROR';
      fallback_status := 'FAILED';
    when 'WARNING' then
      preferred_status := 'WARNING';
      fallback_status := 'SKIPPED';
    when 'INFO' then
      preferred_status := 'INFO';
      fallback_status := 'PENDING';
    else
      raise exception
        'Unsupported Step 10 migration event_status contract';
  end case;

  if legacy_status_constraint is null then
    -- A plain required text column accepts the canonical event status.
    new.status := preferred_status;
  elsif position(
    pg_catalog.quote_literal(preferred_status)
    in legacy_status_constraint
  ) > 0 then
    new.status := preferred_status;
  elsif position(
    pg_catalog.quote_literal(fallback_status)
    in legacy_status_constraint
  ) > 0 then
    new.status := fallback_status;
  else
    raise exception
      'Deployed migration_events.status contract has no safe Step 10 mapping';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.updated_at := now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_job3_scene_time_bounds()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_start numeric; v_end numeric; v_row jsonb; v_point numeric; v_row_start numeric; v_row_end numeric;
begin
  if new.scene_id is null then return new; end if;
  v_row := to_jsonb(new);
  v_point := nullif(v_row->>'timestamp_seconds','')::numeric;
  v_row_start := nullif(v_row->>'start_seconds','')::numeric;
  v_row_end := nullif(v_row->>'end_seconds','')::numeric;
  select s.start_seconds,s.end_seconds into v_start,v_end from public.asset_scenes s where s.id=new.scene_id and s.asset_id=new.asset_id;
  if not found then raise exception using errcode='23503', message='scene does not belong to asset'; end if;
  if tg_table_name='asset_keyframes' and (v_point < v_start or v_point > v_end) then raise exception using errcode='23514', message='keyframe timestamp must fall within scene'; end if;
  if tg_table_name='scene_actions' and ((v_row_start is not null and v_row_start < v_start) or (v_row_end is not null and v_row_end > v_end)) then raise exception using errcode='23514', message='action timestamps must fall within scene'; end if;
  if tg_table_name='asset_transcript_chunks' and ((v_row_start is not null and v_row_start < v_start) or (v_row_end is not null and v_row_end > v_end)) then raise exception using errcode='23514', message='transcript timestamps must fall within scene'; end if;
  if tg_table_name='ocr_observations' and v_point is not null and (v_point < v_start or v_point > v_end) then raise exception using errcode='23514', message='OCR timestamp must fall within scene'; end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.validate_job4_search_feedback_scope()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_result_asset uuid; v_result_scene uuid;
begin
 if new.search_result_id is not null then select r.asset_id,r.scene_id into v_result_asset,v_result_scene from public.search_results r where r.id=new.search_result_id and r.search_query_id=new.search_query_id; if (new.asset_id is not null and new.asset_id is distinct from v_result_asset) or (new.scene_id is not null and new.scene_id is distinct from v_result_scene) then raise exception using errcode='23514',message='feedback scope mismatch'; end if; end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.validate_job4_search_result_scope()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_scene_start numeric; v_scene_end numeric; v_transcript_scene uuid;
begin
 if new.transcript_chunk_id is not null then select t.scene_id into v_transcript_scene from public.asset_transcript_chunks t where t.id=new.transcript_chunk_id and t.asset_id=new.asset_id; if not found or (new.scene_id is not null and new.scene_id is distinct from v_transcript_scene) then raise exception using errcode='23514',message='transcript scope mismatch'; end if; end if;
 if new.scene_id is not null and new.matched_start_seconds is not null then select s.start_seconds,s.end_seconds into v_scene_start,v_scene_end from public.asset_scenes s where s.id=new.scene_id and s.asset_id=new.asset_id; if new.matched_start_seconds<v_scene_start or new.matched_end_seconds>v_scene_end then raise exception using errcode='23514',message='matched timestamps outside scene'; end if; end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.validate_job4_transcript_embedding_scope()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_scene uuid;
begin
  select t.scene_id into v_scene from public.asset_transcript_chunks t
  where t.id=new.transcript_chunk_id and t.asset_id=new.asset_id;
  if not found then raise exception using errcode='23503', message='transcript chunk does not belong to asset'; end if;
  if new.scene_id is distinct from v_scene then raise exception using errcode='23514', message='embedding scene must match transcript scene'; end if;
  return new;
end $function$
